package demo
import("context";"encoding/json";"fmt";"time";"github.com/jackc/pgx/v5/pgxpool";"github.com/REinstall-SyS/WaitlistFair/internal/allocation")
const OrgID="10000000-0000-4000-8000-000000000001"
func ID(kind,index int)string{return fmt.Sprintf("%08d-0000-4000-8000-%012d",kind,index)}
func Seed(ctx context.Context,db *pgxpool.Pool)error{tx,e:=db.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx);if _,e=tx.Exec(ctx,`SELECT pg_advisory_xact_lock(712345679)`);e!=nil{return e};var exists bool;if e=tx.QueryRow(ctx,`SELECT EXISTS(SELECT 1 FROM organizations WHERE id=$1)`,OrgID).Scan(&exists);e!=nil||exists{return e};if _,e=tx.Exec(ctx,`INSERT INTO organizations(id,name,timezone,demo) VALUES($1,'Northstar University · Demo tutoring center','America/Chicago',true)`,OrgID);e!=nil{return e};people:=[]struct{name,email,role string}{{"Alex Morgan","admin","admin"},{"Emma Chen","emma","tutor"},{"Daniel Brooks","daniel","tutor"},{"Priya Shah","priya","tutor"},{"Nora Williams","nora","student"},{"Maya Patel","maya","student"},{"Leo Martinez","leo","student"},{"Sam Taylor","sam","student"}};for i,p:=range people{user:=ID(20000000,i+1);if _,e=tx.Exec(ctx,`INSERT INTO users(id,email,display_name) VALUES($1,$2,$3)`,user,p.email+"@demo.waitlistfair.test",p.name);e!=nil{return e};if _,e=tx.Exec(ctx,`INSERT INTO memberships(organization_id,user_id,role) VALUES($1,$2,$3)`,OrgID,user,p.role);e!=nil{return e}};subjects:=[]string{"Calculus I","Physics","Intro to programming"};durations:=[]int{45,30,60};for i,name:=range subjects{service:=ID(30000000,i+1);tutor:=ID(40000000,i+1);if _,e=tx.Exec(ctx,`INSERT INTO services(id,organization_id,name,duration_minutes) VALUES($1,$2,$3,$4)`,service,OrgID,name,durations[i]);e!=nil{return e};if _,e=tx.Exec(ctx,`INSERT INTO tutors(id,organization_id,user_id) VALUES($1,$2,$3)`,tutor,OrgID,ID(20000000,i+2));e!=nil{return e};if _,e=tx.Exec(ctx,`INSERT INTO tutor_services(tutor_id,service_id,organization_id) VALUES($1,$2,$3)`,tutor,service,OrgID);e!=nil{return e}};zone,_:=time.LoadLocation("America/Chicago");now:=time.Now().In(zone);day:=time.Date(now.Year(),now.Month(),now.Day()+1,14,0,0,0,zone);for i:=0;i<6;i++{subject:=i%3;start:=day.AddDate(0,0,i/3).Add(time.Duration(subject*2)*time.Hour);state:="available";if i==0||i==5{state="booked"};slot:=ID(50000000,i+1);end:=start.Add(time.Duration(durations[subject])*time.Minute);if _,e=tx.Exec(ctx,`INSERT INTO slots(id,organization_id,tutor_id,service_id,starts_at,ends_at,state) VALUES($1,$2,$3,$4,$5,$6,$7)`,slot,OrgID,ID(40000000,subject+1),ID(30000000,subject+1),start,end,state);e!=nil{return e};if state=="booked"{var claim string;if e=tx.QueryRow(ctx,`INSERT INTO claims(slot_id,organization_id,student_id,starts_at,ends_at,state) VALUES($1,$2,$3,$4,$5,'confirmed') RETURNING id`,slot,OrgID,ID(20000000,8),start,end).Scan(&claim);e!=nil{return e};if _,e=tx.Exec(ctx,`INSERT INTO bookings(slot_id,organization_id,student_id,claim_id) VALUES($1,$2,$3,$4)`,slot,OrgID,ID(20000000,8),claim);e!=nil{return e}}};for i:=0;i<3;i++{windows:=[]allocation.Window{};for d:=0;d<7;d++{start,end:="09:00","20:00";if i==0{start,end="06:00","08:00"};windows=append(windows,allocation.Window{Day:d,Start:start,End:end})};preferences,_:=json.Marshal(allocation.Preferences{Timezone:"America/Chicago",Windows:windows});if _,e=tx.Exec(ctx,`INSERT INTO waitlist_entries(id,organization_id,student_id,service_id,preferences,joined_at) VALUES($1,$2,$3,$4,$5,clock_timestamp()-make_interval(hours=>$6))`,ID(60000000,i+1),OrgID,ID(20000000,i+5),ID(30000000,1),preferences,4-i);e!=nil{return e}};return tx.Commit(ctx)}
